def comic_archive_unzip(filename, image_format):
    """
    Uncompress a zip archive.

    Return the name of the working directory we uncompressed into.
    """
    import zipfile
    with zipfile.ZipFile(filename) as zf:
        zf.extractall()
    return os.path.splitext(filename)[0]


