    For Microsoft SQL Server specifically: fetch the value of the ``XACT_LEVEL``
    variable (see e.g.
    https://docs.microsoft.com/en-us/sql/t-sql/functions/xact-level-transact-sql?view=sql-server-2017).
    Returns ``None`` if it can't be found (unlikely?).
    """
    if isinstance(engine_or_conn, Connection):
        conn = engine_or_conn
    else:
        conn = engine_or_conn.connect()
    try:
        return conn.execute("SELECT @@XACT_LEVEL").scalar()
    finally:
        conn.close()


