def _get_caller_options(callers):
    """Retrieve available caller options for the provided callers.

    Handles special cases like CNVkit that can be in initial or standard
    depending on if fed into Lumpy analysis.
    """
    options = []
    for caller in callers:
        if caller == "lumpy":
            options.append("lumpy")
        elif caller == "cnvkit":
            options.append("cnvkit")
            options.append("cnvkit-initial")
            options.append("cnvkit-standard")
        else:
            options.append(caller)
    return options


