def checksum_dir(scheme, path):
    """Return the checksum (hex digest) of a directory"""
    if scheme == 'sha1':
        return hashlib.sha1(
            '\n'.join(
                os.path.join(root, f)
                for root, dirs, files in os.walk(path)
                for f in files
            ).encode('utf-8')
        ).hexdigest()
    elif scheme == 'md5':
        return hashlib.md5(
            '\n'.join(
                os.path.join(root, f)
                for root, dirs, files in os.walk(path)
                for f in files
            ).encode('utf-8')
        ).hexdigest()
    else:
        raise ValueError('Unknown checksum scheme: %s' % scheme)


