def robust_issubclass(cls, typ) -> bool:
    """
    Similar to issubclass, but if 'typ' is a parametrized generic Type, it is first transformed into its base generic
    class so that the instance check works. It is also robust to Union and Any.

    :param cls:
    :param typ:
    :return:
    """
    if isinstance(typ, type):
        return issubclass(cls, typ)
    elif isinstance(typ, type(Generic)):
        return issubclass(cls, typ.__origin__)
    elif isinstance(typ, type(Union)):
        return any(robust_issubclass(cls, t) for t in typ.__args__)
    elif isinstance(typ, type(Any)):
        return True
    else:
        raise ValueError(f"Unsupported type {typ}")


