def find_crate_version(crate_home: str) -> tuple:
    """ Return a CrateDB version from the given CrateDB home directory """
    crate_version_file = os.path.join(crate_home, "version")
    if not os.path.exists(crate_version_file):
        raise RuntimeError(
            "Could not find a CrateDB version file at {}".format(crate_version_file)
        )
    with open(crate_version_file, "r") as f:
        return tuple(map(int, f.read().strip().split(".")))


