def finish_init(environment, start_web, create_sysadmin, log_syslog=False,
                do_install=True, quiet=False, site_url=None, interactive=False,
                init_db=True):
    """
    Common parts of create and init: Install, init db, start site, sysadmin
    """
    if do_install:
        if not quiet:
            print("Installing...")
        install(environment, site_url=site_url, interactive=interactive)

    if init_db:
        if not quiet:
            print("Initializing database...")
        init_db(environment)

    if start_web:
        if not quiet:
            print("Starting web server...")
        start_web(environment)

    if create_sysadmin:
        if not quiet:
            print("Creating sysadmin user...")
        create_sysadmin(environment)

    if log_syslog:
        if not quiet:
            print("Logging to syslog...")
        log_syslog(environment)

