def do_reduce(features, feature_format, positive_class=None):
    """
    Reduces a set of features to a single value.
    """
    if feature_format == "dict":
        return features
    elif feature_format == "list":
        if positive_class is None:
            raise ValueError("positive_class must be specified for list feature format")
        return features[positive_class]
    else:
        raise ValueError("feature_format must be either 'dict' or 'list'")


def do_inverse_reduce(value, feature_format, positive_class=None):
    """
    Inverts the reduce function.
    """
    if feature_format == "dict":
        return value
    elif feature_format == "list":
        if positive_class is None:
            raise ValueError("positive_class must be specified for list feature format")
        return {positive_class: value, "negative": value - value[positive_class]}
    else:
        raise ValueError("feature_format must be either 'dict' or 'list'")


def do_inverse_map(features, feature_format, positive_class=None):
    """
    Inverts the map function.
    """
    if feature_format == "dict":
        return features
    elif feature_format == "list":
        if positive_class is None:
            raise ValueError("positive_class must be specified for list feature format")
        return {positive_class: features[0], "negative": features[1] + features[0]}
    else:
        raise ValueError("feature_format must be either 'dict' or 'list'")

