def save_dataset(self, dataset, filename=None, fill_value=None,
                     overlay=None, decorate=None, compute=True, **kwargs):
        """Saves the ``dataset`` to a given ``filename``.

        This method creates an enhanced image using `get_enhanced_image`. The
        image is then passed to `save_image`. See both of these functions for
        more details on the arguments passed to this method.

        """
        if filename is None:
            filename = self.get_filename(dataset)
        if filename is None:
            raise ValueError("No filename given")
        if overlay is None:
            overlay = self.get_overlay(dataset)
        if decorate is None:
            decorate = self.get_decorate(dataset)
        if fill_value is None:
            fill_value = self.get_fill_value(dataset)
        if compute:
            image = self.get_enhanced_image(dataset, fill_value=fill_value,
                                            overlay=overlay, decorate=decorate,
                                            **kwargs)
        else:
            image = None
        self.save_image(image, filename, **kwargs)

