def prepare(base_path='data',
            serialize=json.dumps,
            deserialize=json.loads,
            file_ext='json'):
    """After you have added your collections, prepare the database
    for use."""
    if not os.path.exists(base_path):
        os.makedirs(base_path)

    for collection in collections:
        collection_path = os.path.join(base_path, collection)
        if not os.path.exists(collection_path):
            os.makedirs(collection_path)

        for key in collections[collection]:
            file_path = os.path.join(collection_path, key + '.' + file_ext)
            if not os.path.exists(file_path):
                with open(file_path, 'w') as f:
                    f.write(serialize({}))

