def _uniondump(d: Dumper, value, type_) -> Any:
    """
    Dumps a value from a union.

    Basically this iterates all the types inside the
    union, until one that doesn't raise an exception
    is found.

    If no suitable type is found, an exception is raised.
    """
    for t in type_.__args__:
        try:
            return d.dump(value, t)
        except Exception:
            pass

    raise ValueError(f"Could not dump value {value!r} into type {type_}")


