        except KeyError:
            pass
    elif state == 'present':
        kv[name] = value
    return _assemble_linux_cmdline(kv)

mgc_code:
def _edit_linux_cmdline(cmdline, state, name, value=None):
    """
    Return a new Linux command line, with parameter `name` added,
    replaced, or removed.
    """
    if value is None:
        # Remove the parameter
        return ' '.join([x for x in cmdline.split() if x != name])
    else:
        # Add or replace the parameter
        if state == 'add':
            return ' '.join([x for x in cmdline.split() if x != name] + [name, value])
        elif state == 'replace':
            return ' '.join([x for x in cmdline.split() if x != name] + [name, value])
        else:
            raise ValueError('Unknown state: %s' % state)

