def __within2(value, within=None, errmsg=None, dtype=None):
    """validate that a value is in ``within`` and optionally a ``dtype``"""
    if not within:
        raise ValueError("within must be provided")
    if not isinstance(within, (list, tuple)):
        raise ValueError("within must be a list or tuple")
    if not value in within:
        raise ValueError(errmsg or "value must be one of {}".format(within))
    if dtype:
        if not isinstance(value, dtype):
            raise ValueError("value must be of type {}".format(dtype))
    return value

